<script>
  // ====== DỮ LIỆU MÓN ĂN ======
  const products = [
    { id: 1, name: "Gà rán truyền thống", emoji: "🍗", desc: "Đùi gà chiên giòn, đậm đà gia vị bí truyền.", price: 35000 },
