    { id: 3, name: "Gà giòn không xương", emoji: "🍖", desc: "Miếng gà không xương tiện lợi, giòn rụm.", price: 55000 },
    { id: 4, name: "Combo gia đình", emoji: "👨‍👩‍👧", desc: "6 miếng gà + 2 khoai tây chiên + 2 nước ngọt.", price: 199000 },
    { id: 5, name: "Khoai tây chiên", emoji: "🍟", desc: "Khoai tây cắt dày, chiên giòn vàng ươm.", price: 25000 },
    { id: 6, name: "Burger gà giòn", emoji: "🍔", desc: "Bánh burger kẹp gà giòn, rau tươi, sốt đặc biệt.", price: 49000 },
    { id: 7, name: "Gà viên chiên", emoji: "🍢", desc: "Gà viên mềm ngọt, chấm sốt chua ngọt.", price: 39000 },
    { id: 8, name: "Nước ngọt các loại", emoji: "🥤", desc: "Coca, Pepsi, 7Up, nước cam ép tươi.", price: 15000 },
  ];

  // ====== GIỎ HÀNG ======
  let cart = JSON.parse(localStorage.getItem('chickenCart') || '[]');

  function saveCart() {
    localStorage.setItem('chickenCart', JSON.stringify(cart));
    updateCartUI();
  }

  function addToCart(id) {
    const existing = cart.find(item => item.id === id);
    if (existing) {
      existing.qty += 1;
    } else {
      const p = products.find(p => p.id === id);
      cart.push({ id: p.id, name: p.name, emoji: p.emoji, price: p.price, qty: 1 });
    }
    saveCart();
    showToast('Đã thêm vào giỏ hàng! 🍗');
  }

  function changeQty(id, delta) {
    const item = cart.find(i => i.id === id);
    if (!item) return;
    item.qty += delta;
    if (item.qty <= 0) cart = cart.filter(i => i.id !== id);
    saveCart();
  }

  function removeItem(id) {
    cart = cart.filter(i => i.id !== id);
    saveCart();
  }

  function cartTotal() {
    return cart.reduce((sum, i) => sum + i.price * i.qty, 0);
  }

  function formatPrice(n) {
    return n.toLocaleString('vi-VN') + 'đ';
  }

  function updateCartUI() {
    const count = cart.reduce((s, i) => s + i.qty, 0);
    document.getElementById('cartCount').textContent = count;

    const itemsEl = document.getElementById('cartItems');
    const footerEl = document.getElementById('cartFooter');

    if (cart.length === 0) {
      itemsEl.innerHTML = '<div class="empty-cart">🛒 Giỏ hàng đang trống<br>Hãy thêm món ngon nhé!</div>';
      footerEl.style.display = 'none';
    } else {
      footerEl.style.display = 'block';
      itemsEl.innerHTML = cart.map(item => `
        <div class="cart-item">
          <div class="item-emoji">${item.emoji}</div>
          <div class="item-info">
            <h4>${item.name}</h4>
            <div class="item-price">${formatPrice(item.price)}</div>
            <button class="remove-btn" onclick="removeItem(${item.id})">Xóa</button>
          </div>
          <div class="qty-controls">
            <button class="qty-btn" onclick="changeQty(${item.id}, -1)">−</button>
            <span>${item.qty}</span>
            <button class="qty-btn" onclick="changeQty(${item.id}, 1)">+</button>
          </div>
        </div>
      `).join('');
      document.getElementById('cartTotal').textContent = formatPrice(cartTotal());
    }
  }

  function openCart() {
    document.getElementById('cartDrawer').classList.add('open');
    document.getElementById('cartOverlay').classList.add('open');
  }

  function closeCart() {
    document.getElementById('cartDrawer').classList.remove('open');
    document.getElementById('cartOverlay').classList.remove('open');
  }

  function checkout() {
    if (cart.length === 0) return;
    showToast('Cảm ơn bạn! Đơn hàng đã được ghi nhận. 🎉');
    cart = [];
    saveCart();
    closeCart();
  }

  // ====== TOAST ======
  let toastTimer;
  function showToast(msg) {
    const t = document.getElementById('toast');
    t.textContent = msg;
    t.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => t.classList.remove('show'), 2200);
  }

  // ====== RENDER MENU ======
  function renderMenu() {
    document.getElementById('menuGrid').innerHTML = products.map(p => `
      <div class="card">
        <div class="card-img">${p.emoji}</div>
        <div class="card-body">
          <h3>${p.name}</h3>
          <p class="desc">${p.desc}</p>
          <div class="card-footer">
            <span class="price">${formatPrice(p.price)}</span>
            <button class="add-btn" onclick="addToCart(${p.id})" title="Thêm vào giỏ">+</button>
          </div>
        </div>
      </div>
    `).join('');
  }

  // ====== FILL ORDER SELECT ======
  function fillOrderSelect() {
    const sel = document.getElementById('orderItem');
    sel.innerHTML = products.map(p => `<option value="${p.name}">${p.name} - ${formatPrice(p.price)}</option>`).join('');
  }

  // ====== ORDER FORM ======
  function handleOrder(e) {
    e.preventDefault();
    showToast('Đặt hàng thành công! Chúng tôi sẽ gọi xác nhận ngay. 📞');
    e.target.reset();
  }

  // ====== INIT ======
  renderMenu();
  fillOrderSelect();
  updateCartUI();
</script>
</body>
</html>
