    padding: 16px;
  }
  .wrap {
    text-align: center;
    width: min(900px, 100%);
  }
  h1 {
    font-size: clamp(1.4rem, 4vw, 2.2rem);
    color: #535353;
    margin-bottom: 4px;
    letter-spacing: -0.5px;
  }
  .sub {
    color: #9a9a9a;
    font-size: 0.95rem;
