  canvas {
    display: block;
    width: 100%;
    height: auto;
    background: #ffffff;
  }
  .hud {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 18px;
    background: #ffffff;
    border-top: 2px solid #e0e0e0;
    font-weight: 700;
    color: #535353;
  }
  .hud .score { font-size: 1.1rem; }
  .hud .score span { color: var(--red); }
  .hud .best { font-size: 0.9rem; color: #9a9a9a; }
  .btn {
    font-family: inherit;
    font-weight: 700;
    border: 2px solid #535353;
    background: #fff;
    color: #535353;
    padding: 8px 16px;
    border-radius: 999px;
    cursor: pointer;
    font-size: 0.9rem;
    transition: all 0.15s;
  }
  .btn:hover { background: #535353; color: #fff; }
  .overlay {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
